#!/usr/bin/env node
/**
 * Text-based advisory scan for browser HTML and JavaScript/TypeScript sources.
 * Exit: 0 applicable pass, 1 findings, 2 input/tool error, 3 not applicable.
 */

import { lstat, readFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';

const SUPPORTED_EXTENSIONS = new Set([
  '.html', '.htm', '.js', '.jsx', '.mjs', '.cjs', '.ts', '.tsx', '.mts', '.cts',
]);
const CODE_EXTENSIONS = new Set(['.js', '.jsx', '.mjs', '.cjs', '.ts', '.tsx', '.mts', '.cts']);
const TYPESCRIPT_EXTENSIONS = new Set(['.ts', '.tsx', '.mts', '.cts']);
const EXCLUDED_DIRECTORIES = new Set([
  'node_modules', 'dist', 'build', 'out', 'vendor', 'coverage', '.git',
  '.next', '.nuxt', '.cache', '__pycache__', 'target', 'generated',
  'agent-rules', '.agents',
]);
const GENERATED_MARKERS = [
  'auto-generated', 'autogenerated', '@generated', 'do not edit',
  'generated file', 'generated by',
];

class InputError extends Error {}

function portable(value) {
  return value.split(path.sep).join('/');
}

function shownPath(file) {
  const relative = path.relative(process.cwd(), file);
  return portable(relative || path.basename(file));
}

function quote(value) {
  return JSON.stringify(String(value));
}

function helpText() {
  return `NOT-APPLICABLE mode=help reason="help displayed; no project files were scanned"
Usage:
  node agent-rules/tools/slop-scan.mjs [--root DIR]... [--file FILE]... [--glob PATTERN]...
  node agent-rules/tools/slop-scan.mjs --help

Canonical invocation:
  node agent-rules/tools/slop-scan.mjs --root .

Alternate APIs:
  node agent-rules/tools/slop-scan.mjs --file index.html --file app.js
  node agent-rules/tools/slop-scan.mjs --glob 'src/**/*.ts' --glob '*.html'

With no selectors, --root . is used. Roots are scanned recursively, including
root-level static HTML/JS and src-based projects. Globs support *, **, and ? and
are resolved from the current directory. Normal root scans exclude managed
agent-rules/.agents trees plus generated, test, vendor, dependency, coverage,
and build artifacts. An excluded root, file, or glob is scanned when directly
targeted.

Output distinguishes DETERMINISTIC-FINDING, HEURISTIC-WARNING, MANUAL-REVIEW,
APPLICABLE-PASS, NOT-APPLICABLE, and ERROR with category, stable fingerprint,
file:line evidence, and full-root or partial-selector scope.
Exit 0 is a complete applicable scan with no findings; 1 means findings or a
partial selector scope require review;
2 is input/tool failure; 3 means no supported authored input was applicable.
This lexical scan can report false positives and does not prove that completion
improved quality, that a sink is exploitable, or that absent findings are safe.
Unchanged retries add no evidence; rerun after an edit or a changed hypothesis.`;
}

function parseArguments(arguments_) {
  if (arguments_.length === 1 && arguments_[0] === '--help') return { help: true };
  const selection = { roots: [], files: [], globs: [] };
  for (let index = 0; index < arguments_.length; index += 1) {
    const option = arguments_[index];
    if (!['--root', '--file', '--glob'].includes(option)) throw new InputError(`unknown argument: ${option}`);
    const value = arguments_[index + 1];
    if (value === undefined || value.startsWith('--')) throw new InputError(`${option} requires one value`);
    const destination = { '--root': 'roots', '--file': 'files', '--glob': 'globs' }[option];
    selection[destination].push(value);
    index += 1;
  }
  if (!selection.roots.length && !selection.files.length && !selection.globs.length) selection.roots.push('.');
  return selection;
}

function isGeneratedName(file) {
  const base = path.basename(file);
  return /\.(?:min|bundle)\.(?:js|mjs|cjs)$/i.test(base)
    || /(?:^|[._-])generated(?:[._-]|$)/i.test(base)
    || /\.d\.(?:ts|mts|cts)$/i.test(base);
}

function scopedRelative(file, scopes) {
  const candidates = [...scopes].map((scope) => path.relative(scope, file))
    .filter((relative) => relative && relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative))
    .sort((left, right) => left.split(path.sep).length - right.split(path.sep).length);
  return candidates[0] ?? path.basename(file);
}

function excludedDirectory(relative) {
  return relative.split(path.sep).slice(0, -1).map((part) => part.toLowerCase())
    .find((part) => EXCLUDED_DIRECTORIES.has(part));
}

function isTestFile(relative) {
  const normalized = `/${portable(relative).toLowerCase()}`;
  const base = path.basename(relative).toLowerCase();
  return /\.(?:test|spec)\.[^.]+$/.test(base)
    || normalized.includes('/test/')
    || normalized.includes('/tests/')
    || normalized.includes('/__tests__/');
}

function generatedMarker(text) {
  const head = text.split(/\r?\n/, 10).join('\n').toLowerCase();
  return GENERATED_MARKERS.find((marker) => head.includes(marker));
}

function targetsExcludedDirectory(selector) {
  return path.normalize(selector).split(path.sep)
    .some((part) => EXCLUDED_DIRECTORIES.has(part.toLowerCase()));
}

async function walk(root, candidates, counters, origin, { includeExcluded = false } = {}) {
  const entries = await readdir(root, { withFileTypes: true });
  entries.sort((left, right) => left.name.localeCompare(right.name));
  for (const entry of entries) {
    const file = path.join(root, entry.name);
    if (entry.isSymbolicLink()) {
      counters.excluded += 1;
      continue;
    }
    if (entry.isDirectory()) {
      if (!includeExcluded && EXCLUDED_DIRECTORIES.has(entry.name.toLowerCase())) {
        counters.excluded += 1;
        continue;
      }
      await walk(file, candidates, counters, origin, { includeExcluded });
    } else if (entry.isFile()) {
      const current = candidates.get(path.resolve(file)) ?? new Set();
      current.add(origin);
      candidates.set(path.resolve(file), current);
    }
  }
}

function globBase(pattern) {
  const wildcard = pattern.search(/[?*]/);
  const prefix = wildcard < 0 ? pattern : pattern.slice(0, wildcard);
  const slash = Math.max(prefix.lastIndexOf('/'), prefix.lastIndexOf('\\'));
  const directory = slash < 0 ? '.' : prefix.slice(0, slash) || path.parse(prefix).root || '.';
  return path.resolve(directory);
}

function globExpression(pattern) {
  if (/[\[\]{}]/.test(pattern)) throw new InputError(`glob supports only *, **, and ?: ${pattern}`);
  const normalized = portable(pattern).replace(/^\.\//, '');
  let source = '^';
  for (let index = 0; index < normalized.length; index += 1) {
    const character = normalized[index];
    if (character === '*' && normalized[index + 1] === '*') {
      index += 1;
      if (normalized[index + 1] === '/') {
        index += 1;
        source += '(?:.*/)?';
      } else {
        source += '.*';
      }
    } else if (character === '*') {
      source += '[^/]*';
    } else if (character === '?') {
      source += '[^/]';
    } else {
      source += character.replace(/[|\\{}()[\]^$+?.]/g, '\\$&');
    }
  }
  return new RegExp(`${source}$`, process.platform === 'win32' ? 'i' : '');
}

async function collect(selection) {
  const candidates = new Map();
  const counters = { excluded: 0 };
  const notices = [];
  const errors = [];
  const rootSelectors = new Map();
  const globSelectors = new Map();
  const scopes = new Set(selection.roots.map((root) => path.resolve(root)));
  if (selection.files.length || selection.globs.some((pattern) => !path.isAbsolute(pattern))) scopes.add(process.cwd());
  for (const [index, rootValue] of selection.roots.entries()) {
    const root = path.resolve(rootValue);
    try {
      const information = await lstat(root);
      if (!information.isDirectory() || information.isSymbolicLink()) throw new InputError(`--root is not a regular directory: ${rootValue}`);
      const origin = `root:${index}`;
      const includeExcluded = targetsExcludedDirectory(rootValue);
      rootSelectors.set(origin, { value: rootValue, includeExcluded });
      await walk(root, candidates, counters, origin, { includeExcluded });
    } catch (error) {
      errors.push(`ERROR input=${quote(rootValue)} reason=${quote(error.message)}`);
    }
  }
  for (const fileValue of selection.files) {
    const file = path.resolve(fileValue);
    try {
      const information = await lstat(file);
      if (!information.isFile() || information.isSymbolicLink()) throw new InputError(`--file is not a regular non-symlink file: ${fileValue}`);
      const origins = candidates.get(file) ?? new Set();
      origins.add('file');
      candidates.set(file, origins);
    } catch (error) {
      errors.push(`ERROR input=${quote(fileValue)} reason=${quote(error.message)}`);
    }
  }
  for (const [index, pattern] of selection.globs.entries()) {
    let expression;
    try {
      expression = globExpression(pattern);
    } catch (error) {
      errors.push(`ERROR input=${quote(pattern)} reason=${quote(error.message)}`);
      continue;
    }
    const base = globBase(pattern);
    const origin = `glob:${index}`;
    const includeExcluded = targetsExcludedDirectory(pattern);
    globSelectors.set(origin, { value: pattern, includeExcluded });
    if (path.isAbsolute(pattern)) scopes.add(path.dirname(base));
    const temporary = new Map();
    try {
      const information = await lstat(base);
      if (information.isDirectory() && !information.isSymbolicLink()) {
        await walk(base, temporary, counters, origin, { includeExcluded });
      } else if (information.isFile()) temporary.set(base, new Set([origin]));
      else throw new InputError(`glob base is not a regular path: ${shownPath(base)}`);
    } catch (error) {
      if (error.code === 'ENOENT') {
        notices.push(`NOT-APPLICABLE input=${quote(pattern)} reason="glob base does not exist"`);
        continue;
      }
      errors.push(`ERROR input=${quote(pattern)} reason=${quote(error.message)}`);
      continue;
    }
    let matched = 0;
    for (const [file] of temporary) {
      const target = path.isAbsolute(pattern) ? portable(file) : portable(path.relative(process.cwd(), file));
      if (!expression.test(target.replace(/^\.\//, ''))) continue;
      const origins = candidates.get(file) ?? new Set();
      origins.add(origin);
      candidates.set(file, origins);
      matched += 1;
    }
    if (!matched) notices.push(`NOT-APPLICABLE input=${quote(pattern)} reason="glob matched no files"`);
  }
  return {
    candidates, counters, notices, errors, scopes, rootSelectors, globSelectors,
    hasPartialSelectors: selection.files.length > 0 || selection.globs.length > 0,
  };
}

async function applicableFiles(collection) {
  const records = [];
  const notices = [...collection.notices];
  const errors = [...collection.errors];
  let excluded = collection.counters.excluded;
  for (const [file, origins] of [...collection.candidates].sort(([left], [right]) => left.localeCompare(right))) {
    const directlyTargeted = origins.has('file') || [...origins]
      .some((origin) => collection.rootSelectors.get(origin)?.includeExcluded
        || collection.globSelectors.get(origin)?.includeExcluded);
    const selected = directlyTargeted || [...origins].some((origin) => origin.startsWith('glob:'));
    const extension = path.extname(file).toLowerCase();
    const relative = scopedRelative(file, collection.scopes);
    const skip = excludedDirectory(relative);
    let reason = null;
    if (!SUPPORTED_EXTENSIONS.has(extension)) reason = `unsupported extension ${extension || '(none)'}`;
    else if (!directlyTargeted && skip) reason = `managed/generated/vendor/build directory ${skip}`;
    else if (!directlyTargeted && isTestFile(relative)) reason = 'test fixture/source is excluded from the production scan';
    else if (!directlyTargeted && isGeneratedName(file)) reason = 'generated, declaration, minified, or bundled filename';
    if (reason) {
      excluded += 1;
      if (selected) notices.push(`NOT-APPLICABLE file=${quote(shownPath(file))} reason=${quote(reason)}`);
      continue;
    }
    try {
      const text = await readFile(file, 'utf8');
      const marker = generatedMarker(text);
      if (marker && !directlyTargeted) {
        excluded += 1;
        if (selected) notices.push(`NOT-APPLICABLE file=${quote(shownPath(file))} reason=${quote(`generated marker ${marker}`)}`);
        continue;
      }
      records.push({
        file, shown: shownPath(file), extension, text, origins,
        lines: text.replaceAll('\r\n', '\n').replaceAll('\r', '\n').split('\n'),
      });
    } catch (error) {
      errors.push(`ERROR file=${quote(shownPath(file))} reason=${quote(`cannot read file: ${error.message}`)}`);
    }
  }
  const applicableRoots = new Set(records.flatMap((record) => [...record.origins].filter((origin) => origin.startsWith('root:'))));
  for (const [origin, rootSelector] of collection.rootSelectors) {
    if (!applicableRoots.has(origin)) {
      notices.push(`NOT-APPLICABLE input=${quote(rootSelector.value)} reason="root contained no supported non-generated authored files"`);
    }
  }
  const fullProjectScan = collection.rootSelectors.size > 0
    && !collection.hasPartialSelectors
    && applicableRoots.size === collection.rootSelectors.size;
  return {
    records, notices, errors, excluded, fullProjectScan,
    hasPartialSelectors: collection.hasPartialSelectors,
    scope: collection.hasPartialSelectors ? 'partial-selector' : 'full-root',
  };
}

function normalizedEvidence(line) {
  return line.trim().replaceAll(/\s+/g, ' ');
}

function evidenceText(line) {
  const trimmed = normalizedEvidence(line);
  return trimmed.length > 180 ? `${trimmed.slice(0, 177)}...` : trimmed;
}

function addLineFindings(findings, record, expression, severity, category, guidance) {
  record.lines.forEach((line, index) => {
    expression.lastIndex = 0;
    if (!expression.test(line)) return;
    findings.push({
      severity, category, file: record.shown, line: index + 1,
      evidence: evidenceText(line), fingerprintEvidence: normalizedEvidence(line), guidance,
    });
  });
}

function escapeExpression(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function scan(records, { fullProjectScan }) {
  const findings = [];
  for (const record of records) {
    addLineFindings(
      findings, record,
      /\b(?:innerHTML|outerHTML|insertAdjacentHTML|document\.write|dangerouslySetInnerHTML)\b/g,
      'DETERMINISTIC-FINDING', 'unsafe-html-sink',
      'Trace untrusted data to the sink; prefer text APIs or framework escaping.',
    );
    addLineFindings(
      findings, record,
      /\b(?:escapeHtml|sanitizeHtml|escapeHTML|sanitizeHTML)\b|\bfunction\s+(?:escapeh|sanitizeh)[A-Za-z0-9_$]*/gi,
      'HEURISTIC-WARNING', 'custom-escaper',
      'Inspect the implementation and sink context before treating it as safe or unsafe.',
    );
    addLineFindings(
      findings, record,
      /\b(?:setTimeout|setInterval)\s*\(/g,
      'MANUAL-REVIEW', 'timer',
      'Verify the timer is required and does not fabricate latency or loading for synchronous work.',
    );
    addLineFindings(
      findings, record,
      /\b(?:localStorage|sessionStorage)\b/g,
      'MANUAL-REVIEW', 'storage',
      'Inspect unavailable storage, corrupt data, recovery, and overwrite behavior.',
    );
    record.lines.forEach((line, index) => {
      if (!/\b(?:TODO|FIXME)\b/.test(line) || /#[0-9]+|[A-Z]{2,}-[0-9]+/.test(line)) return;
      findings.push({
        severity: 'MANUAL-REVIEW', category: 'todo-without-inline-reference', file: record.shown,
        line: index + 1, evidence: evidenceText(line), fingerprintEvidence: normalizedEvidence(line),
        guidance: 'Check whether the marker is tracked elsewhere, then link or resolve it.',
      });
    });
  }

  if (fullProjectScan) {
    for (const record of records.filter((candidate) => TYPESCRIPT_EXTENSIONS.has(candidate.extension) && !/\.d\.(?:ts|mts|cts)$/i.test(path.basename(candidate.file)))) {
      record.lines.forEach((line, index) => {
        const match = line.match(/^\s*export\s+(?:const|function|class|type|interface|enum)\s+([A-Za-z_$][\w$]*)/);
        if (!match) return;
        const symbol = new RegExp(`\\b${escapeExpression(match[1])}\\b`);
        const referenced = records.some((other) => other.file !== record.file && symbol.test(other.text));
        if (!referenced) findings.push({
          severity: 'HEURISTIC-WARNING', category: 'possibly-dead-export', file: record.shown,
          line: index + 1, evidence: evidenceText(line), fingerprintEvidence: normalizedEvidence(line),
          guidance: 'Verify public, type-only, generated, and dynamic consumers before removal.',
        });
      });
    }

    for (const record of records) {
      const base = path.basename(record.file);
      const stem = path.basename(record.file, path.extname(record.file));
      if (/^(?:index|main)\.(?:html?|[cm]?[jt]sx?)$/i.test(base)) continue;
      const expression = CODE_EXTENSIONS.has(record.extension)
        ? new RegExp(`(?:[/"'])${escapeExpression(stem)}(?:\\.(?:ts|tsx|js|jsx|mjs|cjs|mts|cts))?["']`, 'i')
        : new RegExp(escapeExpression(base), 'i');
      const referenced = records.some((other) => other.file !== record.file && expression.test(other.text));
      if (!referenced) findings.push({
        severity: 'HEURISTIC-WARNING', category: 'unreferenced-file', file: record.shown,
        line: 1, evidence: base, fingerprintEvidence: normalizedEvidence(base),
        guidance: 'Verify routing, conventions, generation, and dynamic consumers before deletion.',
      });
    }
  }

  const order = new Map([['DETERMINISTIC-FINDING', 0], ['HEURISTIC-WARNING', 1], ['MANUAL-REVIEW', 2]]);
  const sorted = findings.sort((left, right) => left.file.localeCompare(right.file)
    || left.line - right.line
    || order.get(left.severity) - order.get(right.severity)
    || left.category.localeCompare(right.category));
  return sorted.map((finding) => {
    const identity = `${finding.category}\n${portable(finding.file)}\n${finding.fingerprintEvidence}`;
    const digest = createHash('sha256').update(identity).digest('hex').slice(0, 16);
    return { ...finding, fingerprint: `slop-v1-${digest}` };
  });
}

function findingOutput(finding) {
  return `${finding.severity} category=${finding.category} evidence=${quote(`${finding.file}:${finding.line}`)} fingerprint=${quote(finding.fingerprint)} snippet=${quote(finding.evidence)} guidance=${quote(finding.guidance)}`;
}

async function main() {
  let selection;
  try {
    selection = parseArguments(process.argv.slice(2));
  } catch (error) {
    console.error(`ERROR reason=${quote(error.message)}`);
    return 2;
  }
  if (selection.help) {
    console.log(helpText());
    return 0;
  }
  let collection;
  try {
    collection = await collect(selection);
  } catch (error) {
    console.error(`ERROR reason=${quote(error.message)}`);
    return 2;
  }
  const applicable = await applicableFiles(collection);
  for (const notice of applicable.notices) console.log(notice);
  if (applicable.errors.length) {
    for (const error of applicable.errors) console.error(error);
    console.error(`ERROR summary files=0 scope=${applicable.scope} excluded=${applicable.excluded} failures=${applicable.errors.length} reason="input or filesystem failure prevented a trustworthy scan"`);
    return 2;
  }
  if (!applicable.records.length) {
    console.log(`NOT-APPLICABLE summary files=0 scope=${applicable.scope} excluded=${applicable.excluded} reason="no supported non-generated HTML, JavaScript, or TypeScript files matched"`);
    return 3;
  }
  const findings = scan(applicable.records, applicable);
  const partial = !applicable.fullProjectScan || applicable.notices.length > 0;
  if (partial) {
    const reason = applicable.hasPartialSelectors
      ? '--file and --glob do not establish a complete project graph; use --root when dead-export or unreferenced-file checks are relevant'
      : 'one or more --root selectors contained no applicable authored files, so the requested project set was incomplete';
    console.log(`NOT-APPLICABLE category=project-wide-reference-checks scope=${applicable.scope} reason=${quote(reason)}`);
  }
  for (const finding of findings) console.log(findingOutput(finding));
  const deterministic = findings.filter((finding) => finding.severity === 'DETERMINISTIC-FINDING').length;
  const heuristic = findings.filter((finding) => finding.severity === 'HEURISTIC-WARNING').length;
  const manual = findings.filter((finding) => finding.severity === 'MANUAL-REVIEW').length;
  if (findings.length || partial) {
    const reason = findings.length
      ? partial
        ? 'findings and not-applicable project-wide checks require disposition; scan completion is not proof of quality'
        : 'findings require disposition; scan completion is not proof of quality'
      : 'not-applicable project-wide checks require disposition; scan completion is not proof of quality';
    const notApplicableCategories = applicable.notices.length + (applicable.fullProjectScan ? 0 : 1);
    console.log(`ADVISORY summary files=${applicable.records.length} scope=${applicable.scope} excluded=${applicable.excluded} deterministic-findings=${deterministic} heuristic-warnings=${heuristic} manual-review=${manual} not-applicable-categories=${notApplicableCategories} reason=${quote(reason)}`);
    return 1;
  }
  console.log(`APPLICABLE-PASS summary files=${applicable.records.length} scope=${applicable.scope} excluded=${applicable.excluded} deterministic-findings=0 heuristic-warnings=0 manual-review=0 reason="supported authored files were scanned and no configured pattern matched"`);
  return 0;
}

main()
  .then((code) => { process.exitCode = code; })
  .catch((error) => {
    console.error(`ERROR reason=${quote(error.message)}`);
    process.exitCode = 2;
  });
